"""Stability test for exported model texture filenames in 2_Output_Models.

pytest SluggiesTools/tests/test_filenames.py

Every PNG filename produced by the export pipeline is a deterministic product
of Dolphin's naming convention plus the texture/TLUT hashing performed by
``tpl.TEX.dolphinTextureBasenameForPayload``::

    tex{N}_{W}x{H}_{texhash}[_{tluthash}]_{format}.png

  * ``tex{N}``      texture index inside the TPL
  * ``{W}x{H}``     pixel dimensions
  * ``{texhash}``   16-hex-char xxh64 of the encoded image payload
  * ``_{tluthash}`` 16-hex-char xxh64 of the palette (TLUT) payload, present
                    only for indexed formats (C4/C8/C14X2)
  * ``{format}``    the GX image format code (e.g. 4=RGB565, 9=C8, 14=CMPR)

Because the hashes are computed from the *encoded* bytes, any change in the
workflow (re-encoding, untangling, a new/removed texture, a dimension or
format change, a changed TLUT) changes the resulting filename. This test pins
the full set of exported model texture filenames so a regression that renames
any exported PNG is caught immediately, with the exact affected names reported.

Scope
-----
Only **model textures** are checked: every ``.png`` under ``2_Output_Models``
that is NOT inside the icon pipeline (``_ICONS``) and NOT in the scratch space
(``tex_temp``). Icon sheets, icon metadata, and palette-only artifacts are
intentionally out of scope. (Indexed textures carry their palette hash inside
the same ``tex*.png`` filename, so they are model textures and are included.)

Regenerating the baseline
-------------------------
When a workflow change *intentionally* changes the exported filenames, update
the baseline by running::

    python SluggiesTools/tests/test_filenames.py --regenerate

which rewrites the ``EXPECTED_MODEL_TEXTURES`` list in place (between the
BEGIN/END markers). Then review the git diff to confirm the renames are the
expected ones.
"""

from __future__ import annotations

import pathlib
import re
import sys
import unittest

# ---------------------------------------------------------------------------
# Paths & scope
# ---------------------------------------------------------------------------

REPO_ROOT = pathlib.Path(__file__).resolve().parents[2]
OUTPUT_DIR = REPO_ROOT / "2_Output_Models"

# Directories that are not model textures and must be ignored:
#   _ICONS   -> icon export / reimport pipeline (sheets, raw, metadata)
#   tex_temp -> per-export scratch space (cleared on each export)
EXCLUDED_DIR_NAMES = frozenset({"_ICONS", "tex_temp"})

# Dolphin texture PNG naming convention (see module docstring).
TEX_PNG_RE = re.compile(
    r"^tex\d+_\d+x\d+_[0-9a-fA-F]{16}(?:_[0-9a-fA-F]{16})?_\d+\.png$"
)

# ---------------------------------------------------------------------------
# Baseline (regenerate with ``--regenerate``)
# ---------------------------------------------------------------------------

