# ---------------------------------------------------------------------------
# Collection helpers
# ---------------------------------------------------------------------------

def collect_model_texture_paths(output_dir: pathlib.Path = OUTPUT_DIR) -> set[str]:
    """Return the set of relative (posix) paths of model texture PNGs.

    A *model texture* is any ``.png`` under ``output_dir`` that is not located
    inside an excluded directory (``_ICONS`` / ``tex_temp``).
    """
    found: set[str] = set()
    for path in output_dir.rglob("*.png"):
        rel = path.relative_to(output_dir)
        if any(part in EXCLUDED_DIR_NAMES for part in rel.parts):
            continue
        found.add(rel.as_posix())
    return found


def non_dolphin_named(model_paths: set[str]) -> list[str]:
    """Return model texture PNGs whose basename breaks the Dolphin convention."""
    return sorted(
        rel for rel in model_paths if not TEX_PNG_RE.match(rel.rsplit("/", 1)[-1])
    )


def _build_list_literal(paths: list[str]) -> str:
    """Render a sorted list of paths as a Python list literal."""
    escaped = [p.replace("\\", "\\\\").replace('"', '\\"') for p in paths]
    entries = ",\n".join(f'    "{p}"' for p in escaped)
    return "EXPECTED_MODEL_TEXTURES = [\n" + entries + ",\n]"


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------

class ModelTextureFilenameTests(unittest.TestCase):
    def test_model_texture_filenames_unchanged(self):
        if not OUTPUT_DIR.is_dir():
            self.skipTest(f"{OUTPUT_DIR} does not exist (run an export first)")

        expected = set(EXPECTED_MODEL_TEXTURES)
        actual = collect_model_texture_paths()

        missing = sorted(expected - actual)  # baseline names no longer exported
        extra = sorted(actual - expected)    # newly exported names not in baseline

        if not missing and not extra:
            return

        lines = [
            f"Model texture filename set changed: "
            f"{len(missing)} missing, {len(extra)} unexpected "
            f"(baseline={len(expected)}, current={len(actual)})."
        ]
        if missing:
            lines.append("MISSING (in baseline, no longer exported):")
            lines.extend(f"  - {name}" for name in missing)
        if extra:
            lines.append("UNEXPECTED (exported, not in baseline):")
            lines.extend(f"  + {name}" for name in extra)
        self.fail("\n".join(lines))

    def test_all_model_textures_follow_dolphin_naming(self):
        if not OUTPUT_DIR.is_dir():
            self.skipTest(f"{OUTPUT_DIR} does not exist (run an export first)")

        offenders = non_dolphin_named(collect_model_texture_paths())
        self.assertEqual(
            offenders,
            [],
            "Model texture PNGs that do not follow the Dolphin naming "
            "convention (tex{N}_{W}x{H}_{texhash}[_{tluthash}]_{format}.png):\n"
            + "\n".join(f"  - {name}" for name in offenders),
        )


# ---------------------------------------------------------------------------
# Baseline regeneration
# ---------------------------------------------------------------------------

def regenerate_baseline() -> None:
    """Rewrite EXPECTED_MODEL_TEXTURES in this file from the current export."""
    if not OUTPUT_DIR.is_dir():
        raise SystemExit(f"{OUTPUT_DIR} does not exist (run an export first)")

    paths = sorted(collect_model_texture_paths())
    block = (
        "# BEGIN EXPECTED_MODEL_TEXTURES\n"
        + _build_list_literal(paths)
        + "\n# END EXPECTED_MODEL_TEXTURES"
    )

    here = pathlib.Path(__file__).resolve()
    text = here.read_text(encoding="utf-8")
    begin = text.index("# BEGIN EXPECTED_MODEL_TEXTURES")
    end = text.index("# END EXPECTED_MODEL_TEXTURES") + len(
        "# END EXPECTED_MODEL_TEXTURES"
    )
    here.write_text(text[:begin] + block + text[end:], encoding="utf-8", newline="\n")
    print(f"Regenerated baseline: {len(paths)} model texture filenames -> {here}")


if __name__ == "__main__":
    if "--regenerate" in sys.argv:
        regenerate_baseline()
    else:
        unittest.main()

